import React, { useEffect, useState, useRef } from 'react';
import api from '../utils/api';
import Chart from 'chart.js/auto';

const ChartComponent = () => {
    const [data, setData] = useState({ invoices: [], flights: [] });
    const [error, setError] = useState(null);
    const [startDate, setStartDate] = useState('2023-01-01');
    const [endDate, setEndDate] = useState('2024-12-31');
    const [selectedAircrafts, setSelectedAircrafts] = useState([]);
    const chartRef = useRef(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                // Assume data parsing logic is applied at the API level as discussed
                setData(result.data);
            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        fetchData();
    }, []);

    useEffect(() => {
        if (data.flights.length > 0 && data.invoices.length > 0) {
            const ctx = chartRef.current.getContext('2d');
            const filteredFlights = data.flights.filter(flight => 
                new Date(flight['Start Z']) >= new Date(startDate) && new Date(flight['Start Z']) <= new Date(endDate)
            );
            const revenueData = filteredFlights.reduce((acc, flight) => {
                const invoice = data.invoices.find(inv => inv.Trip === flight.Trip && inv.Aircraft === flight.Aircraft);
                if (invoice && (selectedAircrafts.length === 0 || selectedAircrafts.includes(flight.Aircraft))) {
                    acc[flight.Aircraft] = acc[flight.Aircraft] || { totalHours: 0, totalPrice: 0 };
                    acc[flight.Aircraft].totalHours += flight['Flight hrs'];
                    acc[flight.Aircraft].totalPrice += invoice.Price;
                }
                return acc;
            }, {});

            const chartData = {
                labels: Object.keys(revenueData),
                datasets: [{
                    label: 'Revenue Per Hour',
                    data: Object.values(revenueData).map(data => (data.totalHours ? data.totalPrice / data.totalHours : 0)),
                    backgroundColor: 'rgba(75, 192, 192, 0.2)',
                    borderColor: 'rgba(75, 192, 192, 1)',
                    borderWidth: 1
                }]
            };

            new Chart(ctx, {
                type: 'bar',
                data: chartData,
                options: {
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });
        }
    }, [data, startDate, endDate, selectedAircrafts]);

    return (
        <div>
            <h1>Aircraft Revenue Analysis</h1>
            <div>
                Start Date:
                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} />
                End Date:
                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} />
                Aircraft:
                <select multiple value={selectedAircrafts} onChange={e => setSelectedAircrafts([...e.target.selectedOptions].map(option => option.value))}>
                    {Array.from(new Set(data.flights.map(flight => flight.Aircraft))).map(aircraft => (
                        <option key={aircraft} value={aircraft}>{aircraft}</option>
                    ))}
                </select>
            </div>
            <canvas ref={chartRef} width="400" height="400"></canvas>
        </div>
    );
};

export default ChartComponent;
